root = std::make_shared<Node>();
int num_chars;
infile.read(reinterpret_cast<char*>(&num_chars), sizeof(num_chars));

for (int i = 0; i < num_chars; i++) {
    unsigned char ch;
    int code_length;
    infile.read(reinterpret_cast<char*>(&ch), sizeof(ch));
    infile.read(reinterpret_cast<char*>(&code_length), sizeof(code_length));

    std::vector<bool> code_bits(code_length);
    for (int j = 0; j < code_length; j++) {
        unsigned char byte;
        int bit_index;
        if (j % 8 == 0) {
            infile.read(reinterpret_cast<char*>(&byte), sizeof(byte));
        }
        bit_index = j % 8;
        unsigned char mask = 1 << (7 - bit_index);
        code_bits[j] = (byte & mask) != 0;
    }

    auto current = root;
    for (int j = 0; j < code_length; j++) {
        if (code_bits[j]) {
            if (!current->right) {
                current->right = std::make_shared<Node>();
            }
            current = current->right;
        } else {
            if (!current->left) {
                current->left = std::make_shared<Node>();
            }
            current = current->left;
        }
    }
    current->ch = ch;
    current->is_leaf = true;
}
// END_CODE

